Rule.Source:
import sailpoint.object.Application;
import sailpoint.object.QueryOptions;
import sailpoint.object.Filter;
import sailpoint.connector.ConnectorFactory;
import sailpoint.connector.Connector;
import java.util.List;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.Date;
import java.text.SimpleDateFormat;
import java.io.FileWriter;
import java.io.BufferedWriter;

String reportPath = "/tmp/iiq_connector_report.html";
SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss");
String ts = sdf.format(new Date());

QueryOptions qo = new QueryOptions();
qo.add(Filter.notnull("type"));
qo.add(Filter.ne("type", ""));
List apps = context.getObjects(Application.class, qo);

List results = new ArrayList();
int pass = 0, fail = 0, skip = 0;

for (Object obj : apps) {
    Application app = (Application) obj;
    HashMap row = new HashMap();
    row.put("name", app.getName());
    row.put("type", app.getType() != null ? app.getType() : "N/A");

    if (app.isDisabled()) {
        row.put("status",  "SKIPPED");
        row.put("reason",  "Application desactivee");
        row.put("elapsed", "-");
        results.add(row);
        skip++;
        continue;
    }

    long t0 = System.currentTimeMillis();
    try {
        Connector c = ConnectorFactory.getConnector(app, null);
        if (c == null) {
            row.put("status",  "SKIPPED");
            row.put("reason",  "ConnectorFactory null");
            row.put("elapsed", "-");
            results.add(row);
            skip++;
            continue;
        }
        c.testConfiguration();
        long ms = System.currentTimeMillis() - t0;
        row.put("status",  "SUCCESS");
        row.put("reason",  "");
        row.put("elapsed", ms + " ms");
        pass++;
    } catch (Exception e) {
        long ms = System.currentTimeMillis() - t0;
        String msg = e.getMessage() != null ? e.getMessage() : e.getClass().getName();
        if (msg.length() > 150) msg = msg.substring(0, 150) + "...";
        msg = msg.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;");
        row.put("status",  "FAILURE");
        row.put("reason",  msg);
        row.put("elapsed", ms + " ms");
        fail++;
    }
    results.add(row);
}

// Construction des lignes HTML
StringBuilder rows = new StringBuilder();
for (int i = 0; i < results.size(); i++) {
    HashMap r = (HashMap) results.get(i);
    String st  = (String) r.get("status");
    String css = "SUCCESS".equals(st) ? "s" : "FAILURE".equals(st) ? "f" : "k";
    rows.append("<tr class='r").append(css).append("'>");
    rows.append("<td>").append(r.get("name")).append("</td>");
    rows.append("<td>").append(r.get("type")).append("</td>");
    rows.append("<td>").append(st).append("</td>");
    rows.append("<td>").append(r.get("elapsed")).append("</td>");
    rows.append("<td>").append(r.get("reason")).append("</td>");
    rows.append("</tr>\n");
}

// HTML minimal mais fonctionnel
String html = "<html><head><meta charset='UTF-8'/><title>IIQ Connectors</title>"
+ "<style>body{font-family:monospace;background:#0b0e14;color:#c9d1e0;padding:2rem}"
+ "h1{color:#00d4ff;margin-bottom:1rem}"
+ ".kpis{display:flex;gap:1rem;margin-bottom:1.5rem}"
+ ".kpi{background:#111621;border:1px solid #1e2433;border-radius:8px;padding:1rem 1.5rem}"
+ ".kpi label{font-size:.7rem;color:#4a5568;display:block}"
+ ".kpi span{font-size:2rem;font-weight:bold}"
+ ".t span{color:#00d4ff}.s span{color:#00e5a0}.f span{color:#ff4d6d}.k span{color:#f0a500}"
+ "input{background:#111621;border:1px solid #1e2433;color:#c9d1e0;padding:.5rem 1rem;"
+ "border-radius:6px;font-family:monospace;font-size:.8rem;width:100%;margin-bottom:1rem}"
+ "table{width:100%;border-collapse:collapse;background:#111621;border-radius:8px;overflow:hidden}"
+ "th{font-size:.65rem;text-transform:uppercase;color:#4a5568;padding:.7rem 1rem;"
+ "text-align:left;border-bottom:1px solid #1e2433}"
+ "td{padding:.7rem 1rem;border-bottom:1px solid #1e2433;font-size:.8rem}"
+ "tr:last-child td{border-bottom:none}"
+ ".rs td:first-child{color:#00e5a0}"
+ ".rf td:first-child{color:#ff4d6d}"
+ ".rk td:first-child{color:#4a5568}"
+ ".msg{color:#ff4d6d;font-size:.72rem}"
+ "</style></head><body>"
+ "<h1>SailPoint IIQ 8.4p3 — Rapport Connecteurs</h1>"
+ "<p style='color:#4a5568;font-size:.75rem;margin-bottom:1.5rem'>Genere le : " + ts + "</p>"
+ "<div class='kpis'>"
+ "<div class='kpi t'><label>TOTAL</label><span>" + results.size() + "</span></div>"
+ "<div class='kpi s'><label>SUCCESS</label><span>" + pass + "</span></div>"
+ "<div class='kpi f'><label>FAILURE</label><span>" + fail + "</span></div>"
+ "<div class='kpi k'><label>SKIPPED</label><span>" + skip + "</span></div>"
+ "</div>"
+ "<input type='text' id='q' placeholder='Filtrer...' oninput='go()'/>"
+ "<table><thead><tr>"
+ "<th>Application</th><th>Type</th><th>Statut</th><th>Duree</th><th>Message</th>"
+ "</tr></thead><tbody id='tb'>"
+ rows.toString()
+ "</tbody></table>"
+ "<script>function go(){var q=document.getElementById('q').value.toLowerCase();"
+ "var rows=document.querySelectorAll('#tb tr');"
+ "rows.forEach(function(r){r.style.display=r.textContent.toLowerCase().includes(q)?'':'none';});}"
+ "</script></body></html>";

BufferedWriter w = new BufferedWriter(new FileWriter(reportPath));
w.write(html);
w.close();

System.out.println("[DONE] SUCCESS=" + pass + " FAILURE=" + fail + " SKIPPED=" + skip);
System.out.println("[DONE] Rapport: " + reportPath);

return "SUCCESS:" + pass + " | FAILURE:" + fail + " | SKIPPED:" + skip + " | Rapport: " + reportPath;
